     "text": "import numpy as np\nimport torch\nimport torch.nn.functional as F\n\nrng = np.random.default_rng(0)\nn, d = 3, 4                                     # 3 токена, размерность 4\nX = rng.normal(size=(n, d))\nWq, Wk, Wv = (rng.normal(size=(d, d)) / 2 for _ in range(3))\nQ, K, V = X @ Wq, X @ Wk, X @ Wv\n\nscores = Q @ K.T / np.sqrt(d)                   # n × n оценок\nA = np.exp(scores - scores.max(1, keepdims=True)); A /= A.sum(1, keepdims=True)\nout = A @ V\nprint('веса внимания (строка — токен-запрос):\\n', A.round(3))\nprint('суммы строк:', A.sum(1).round(6))\nref = F.scaled_dot_product_attention(*(torch.tensor(m)[None] for m in (Q, K, V)))[0]\nprint('совпадает с F.scaled_dot_product_attention:', np.allclose(out, ref.numpy()))",
