     "t": "code",
     "text": "import torch\n\ntorch.manual_seed(0)\nfor d in [4, 64, 512]:\n    q, k = torch.randn(1000, 1, d), torch.randn(1000, 8, d)   # 1000 запросов, у каждого 8 ключей\n    scores = (q * k).sum(-1)                                   # 1000 × 8 скалярных произведений\n    raw = scores.softmax(-1).max(-1).values.mean()\n    scaled = (scores / d ** 0.5).softmax(-1).max(-1).values.mean()\n    print(f'd = {d:3d}: дисперсия q·k = {scores.var():6.1f}; средний максимальный вес softmax: '\n          f'без деления {raw:.2f}, с делением на √d {scaled:.2f}')",
